"""
    Convert a string to title case.

    Title case means that the first character of every word is capitalized
    and all the rest are lowercase.

    Parameters
    ----------
    sentence: string
        String to be converted to title case

    Return
    ------
    titled_sentence: string
        Sentence in a title case

    Examples
    --------
    >>> title_case('THiS iS a sTrInG tO be COnverTeD.')
        'This Is A String To Be Converted.'
    """
def title_case(sentence: Any) -> object {
    if not isinstance(sentence, str) {
        raise TypeError("Input sentence must be type str");
    }
    if (len(sentence) == 0) {
        raise ValueError("Input sentence cannot be empty");
    }
    return sentence.title();
}

"""
    Return the energy for given volume (V - it can be a vector) according to
    the Birch Murnaghan function with parameters E0,V0,B0,B01.
    """
def birch_murnaghan(V: Any, E0: Any, V0: Any, B0: Any, B01: Any) -> object {
    r = (V0 / V) ** (2.0 / 3.0);
    return (
        E0
        + (
            (9.0 / 16.0)
            * B0
            * V0
            * ((((r - 1.0) ** 3) * B01) + (((r - 1.0) ** 2) * (6.0 - (4.0 * r))))
        )
    );
}

